import{_ as a,o as s,c as n,a as l}from"./chunks/framework.Ld7uezS_.js";const c=JSON.parse('{"title":"水系统设备项目卡","description":"","frontmatter":{},"headers":[],"relativePath":"skill/water-system.md","filePath":"skill/water-system.md","lastUpdated":1787292051000}'),r={name:"skill/water-system.md"};function i(o,t,e,d,p,h){return s(),n("div",null,[...t[0]||(t[0]=[l(`<h1 id="水系统设备项目卡" tabindex="-1">水系统设备项目卡 <a class="header-anchor" href="#水系统设备项目卡" aria-label="Permalink to &quot;水系统设备项目卡&quot;">​</a></h1><blockquote><p><strong>定位</strong>：检测维修保养方向的可学习课程，覆盖自动喷水灭火与消防给水。本文用于建立识别、操作、保养、检测和故障闭环，不替代现行标准、设计文件、设备说明书、单位规程或鉴定站评分表。</p></blockquote><h2 id="_1-学习目标与安全边界" tabindex="-1">1. 学习目标与安全边界 <a class="header-anchor" href="#_1-学习目标与安全边界" aria-label="Permalink to &quot;1. 学习目标与安全边界&quot;">​</a></h2><p>学完本卡，应能：</p><ul><li>按“水源—储水—加压—控制—管网—出水—试水排水—反馈”说明水系统链路；</li><li>区分湿式、干式、预作用、雨淋系统的基本工作逻辑；</li><li>识别泵组、报警阀组、阀门、喷头、试水装置及信号部件；</li><li>按方案记录输入、显示、动作、反馈、恢复五项结果；</li><li>对异常先记录、隔离、报告和采取临时防护，不越权拆修。</li></ul><div class="warning custom-block"><p class="custom-block-title">安全边界</p><p>未经授权不得关闭消防给水阀门、切断泵组电源、拆卸喷头或报警阀部件、修改压力设定和联动逻辑。涉及停用、放水、误启动或保护范围变化时，须审批、告知、监护、设置临时防护并完成复核。</p></div><h2 id="_2-系统总览" tabindex="-1">2. 系统总览 <a class="header-anchor" href="#_2-系统总览" aria-label="Permalink to &quot;2. 系统总览&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>消防水源</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>消防水池/高位消防水箱（按设计储水）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>主泵/备用泵 ── 稳压泵及稳压设施</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>报警阀组/控制阀（分区控制）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>配水干管、支管、信号阀、水流指示器</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>闭式或开式喷头 / 室内消火栓</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>末端试水、报警阀试水、排水设施</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>压力开关、水流信号、泵运行/故障反馈 → 消防控制室</span></span></code></pre></div><p>实际分区、共用水源、泵组配置和控制逻辑必须以竣工图、设计文件和设备资料为准，不能从示意图推导工程结论。</p><h2 id="_3-设备识别卡" tabindex="-1">3. 设备识别卡 <a class="header-anchor" href="#_3-设备识别卡" aria-label="Permalink to &quot;3. 设备识别卡&quot;">​</a></h2><p>先把“设备识别卡”理解成一张现场找设备的路线图：不是看见一个泵或阀就记名字，而是沿水流方向确认它处于哪一环、改变什么状态、把什么结果反馈出去。</p><p>零基础识别水系统时，不要只看“有没有一个泵或一个阀”，而要沿着水流方向找对象：<strong>水从哪里来 → 存在哪里 → 由什么加压 → 哪个阀组控制分区 → 通过哪条管网 → 从哪里出水 → 哪个部件把结果反馈到控制室</strong>。</p><p>先区分三个容易混淆的对象：</p><ul><li><strong>控制阀/信号阀</strong>：改变或监视管网通断状态，重点是阀门位置和状态反馈；</li><li><strong>水流指示器</strong>：感知某分区管道中的水流变化，重点是分区信号，不等于测得完整供水能力；</li><li><strong>压力开关</strong>：感知压力变化并输出电信号，重点是压力触发和控制器输入，不等于现场已经完成灭火动作。</li></ul><p>再区分三个证据：</p><ol><li><strong>水力证据</strong>：水位、压力、流量、出水和排水；</li><li><strong>机械/设备证据</strong>：泵是否运行、阀门是否处于规定位置、警铃是否动作；</li><li><strong>控制与反馈证据</strong>：控制柜、控制器、模块是否显示对应状态。</li></ol><p>只有把三类证据对应起来，才能判断问题是在水源、管网、设备动作还是信号反馈层。</p><table tabindex="0"><thead><tr><th>设备</th><th>主要用途</th><th>学习时确认</th></tr></thead><tbody><tr><td>消防水池/水箱</td><td>提供设计消防用水</td><td>水位、补水、溢流、进出水和标识</td></tr><tr><td>主泵/备用泵</td><td>提供灭火所需加压供水</td><td>泵号、吸水/出水阀、控制柜、运行和故障反馈</td></tr><tr><td>稳压泵/稳压设施</td><td>维持管网规定压力</td><td>自动状态、压力显示、频繁启停现象</td></tr><tr><td>报警阀组</td><td>分区控制并输出水流报警</td><td>阀体、试水/排水、警铃、压力开关及阀门状态</td></tr><tr><td>信号阀/控制阀</td><td>控制或监视管网通断</td><td>常开、锁定/铅封、状态反馈和标识</td></tr><tr><td>水流指示器</td><td>指示分区管网水流</td><td>分区、方向、信号线、动作和复位</td></tr><tr><td>压力开关</td><td>以压力变化输出信号</td><td>接线、设定由谁维护、启泵/报警反馈</td></tr><tr><td>水力警铃/延迟器</td><td>现场声响报警、减少短时水流误报</td><td>试警铃、排水、堵塞和渗漏</td></tr><tr><td>末端试水装置</td><td>模拟末端放水检查水流和信号</td><td>压力、排水、显示、报警、反馈和复归</td></tr><tr><td>喷头</td><td>按系统类型出水灭火</td><td>类型、完好、遮挡、污染、改造和动作后处理</td></tr><tr><td>消火栓/接合器</td><td>室内灭火取水、消防车供水</td><td>栓箱、水带水枪、阀门、接口、标识和通道</td></tr></tbody></table><h2 id="_3-1-零基础-先理解静压、动压和流量" tabindex="-1">3.1 零基础：先理解静压、动压和流量 <a class="header-anchor" href="#_3-1-零基础-先理解静压、动压和流量" aria-label="Permalink to &quot;3.1 零基础：先理解静压、动压和流量&quot;">​</a></h2><ul><li><strong>静压</strong>：水基本不流动或流量很小时，在测点表现出的压力；它能帮助判断储水、充水和高度等状态，但不能单独证明出水能力。</li><li><strong>动压</strong>：水正在流动时测得的压力；它会受到流量、管径、沿程阻力、局部构件和高差影响。</li><li><strong>流量</strong>：单位时间通过管道的水量；同样的压力读数，在不同管径、阀门和出水条件下不一定对应相同流量。</li><li><strong>最不利点</strong>：在设计或检测判断中，供水条件相对不利、需要重点核对的部位；具体位置和判定依据要看设计文件及适用标准。</li></ul><p>所以，“压力表有读数”“末端有水”“水泵能转”分别只是局部证据，不能单独推出整个系统供水能力合格。检测时要把水源、阀门、泵组、管网、测点、流量和报警反馈放在同一条证据链中。</p><h3 id="水从水源到末端经过什么" tabindex="-1">水从水源到末端经过什么 <a class="header-anchor" href="#水从水源到末端经过什么" aria-label="Permalink to &quot;水从水源到末端经过什么&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>水源/水池/水箱</span></span>
<span class="line"><span>→ 吸水管和泵组</span></span>
<span class="line"><span>→ 止回、控制和报警阀组</span></span>
<span class="line"><span>→ 分区管网</span></span>
<span class="line"><span>→ 水流指示器/压力开关</span></span>
<span class="line"><span>→ 喷头或消火栓</span></span>
<span class="line"><span>→ 试水、排水和信号反馈</span></span></code></pre></div><p>任何一段阀门关闭、管路堵塞、泵反转、吸水不足、压力异常或信号线路故障，都可能造成“局部看起来正常、整体功能不完整”。</p><h2 id="_3-2-零基础-从-水从哪里来-读懂系统" tabindex="-1">3.2 零基础：从“水从哪里来”读懂系统 <a class="header-anchor" href="#_3-2-零基础-从-水从哪里来-读懂系统" aria-label="Permalink to &quot;3.2 零基础：从“水从哪里来”读懂系统&quot;">​</a></h2><p>把水系统想成一条受控的供水链：<strong>水源提供水，水池/水箱储水，泵组提供压力，阀组决定分区，管网输水，喷头或消火栓出水，试水装置模拟动作，信号部件把结果送回控制室</strong>。任何一环异常，都可能表现为“末端没水”“泵有动作但无压力”或“现场动作、控制室无反馈”。</p><h3 id="水源、消防水池和高位消防水箱" tabindex="-1">水源、消防水池和高位消防水箱 <a class="header-anchor" href="#水源、消防水池和高位消防水箱" aria-label="Permalink to &quot;水源、消防水池和高位消防水箱&quot;">​</a></h3><ul><li><strong>水源</strong>：可以是市政给水、消防水池或其他经设计确认的水源。先看竣工资料和现场标识，不能仅凭一根进水管判断水源可靠。</li><li><strong>消防水池</strong>：在需要时储存消防用水，重点看水位、补水、进出水、溢流、排水、防冻和检修影响。水池有水不等于吸水条件、阀门和水泵都正常。</li><li><strong>高位消防水箱</strong>：利用高差为管网提供水源或初期压力条件，重点看水位、进出水、补水、溢流、管路和防冻。显示水位正常也不能代替对出水和信号的验证。</li></ul><h3 id="消防泵、备用泵和稳压泵" tabindex="-1">消防泵、备用泵和稳压泵 <a class="header-anchor" href="#消防泵、备用泵和稳压泵" aria-label="Permalink to &quot;消防泵、备用泵和稳压泵&quot;">​</a></h3><ul><li><strong>消防主泵/备用泵</strong>：主泵承担主要供水，备用泵在主泵不可用或按设计逻辑切换时提供保障。检测时要同时看电源、控制柜、泵体、吸水/出水条件、压力变化和运行反馈。</li><li><strong>稳压泵</strong>：用于维持管网平时的规定压力，通常功率和供水能力不同于主泵。频繁启停可能与渗漏、压力波动、稳压部件或控制设定有关，不能未经授权改设定。</li><li><strong>压力表/压力传感部件</strong>：用于观察或采集压力。表针有读数不等于读数准确，测量结果应记录仪器、单位、时间、测试条件和适用依据。</li></ul><h3 id="四类系统的动作差异" tabindex="-1">四类系统的动作差异 <a class="header-anchor" href="#四类系统的动作差异" aria-label="Permalink to &quot;四类系统的动作差异&quot;">​</a></h3><ul><li><strong>湿式</strong>：闭式喷头和管网通常处于充水状态，喷头动作后直接出水并形成水流报警；环境适用性要看设计和防冻条件。</li><li><strong>干式</strong>：管网平时主要由有压气体保持，喷头动作后先排气，供水再进入管网；动作链较长，排气、充水和防冻条件要按方案确认。</li><li><strong>预作用</strong>：由预作用控制逻辑控制管网充水，并与喷头或探测条件配合；具体是何种联动逻辑必须查图纸和说明书，不能把名称当作统一动作步骤。</li><li><strong>雨淋</strong>：使用开式喷头，启动后保护区可能集中放水；试验影响较大，须有批准方案、排水和现场监护。</li></ul><h3 id="常见组件-做什么" tabindex="-1">常见组件“做什么” <a class="header-anchor" href="#常见组件-做什么" aria-label="Permalink to &quot;常见组件“做什么”&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>用大白话理解</th><th>适用场景提示</th></tr></thead><tbody><tr><td>报警阀组</td><td>把供水分到保护分区，并在水流出现时组织报警</td><td>湿式、干式等系统按配置使用；阀组形式不能混用</td></tr><tr><td>水流指示器</td><td>发现某一分区管道有水流，并输出分区信号</td><td>重点是分区定位，不单独证明水压或全系统能力</td></tr><tr><td>压力开关</td><td>感知压力变化并输出电信号</td><td>可参与报警或启泵，接线和逻辑以设计为准</td></tr><tr><td>末端试水装置</td><td>在管网末端人为制造可控水流，观察压力、报警和反馈</td><td>只代表测试点的结果，不能外推全系统</td></tr><tr><td>喷头</td><td>在满足动作条件时按类型和方向出水</td><td>闭式/开式、温感元件、喷头方向和遮挡要按资料核对</td></tr><tr><td>消火栓</td><td>为人员提供水带、水枪和取水接口</td><td>检查箱内组件、阀门、通道和标识，不把静态有水当成功能完成</td></tr><tr><td>水泵接合器</td><td>让消防车从建筑外部向室内消防管网补水或加压</td><td>关注位置、接口、止回/放水组件、标识和通道，具体用途看系统设计</td></tr></tbody></table><h3 id="理论关联" tabindex="-1">理论关联 <a class="header-anchor" href="#理论关联" aria-label="Permalink to &quot;理论关联&quot;">​</a></h3><ul><li><strong>燃烧与灭火</strong>：喷水通过冷却、隔绝或抑制火焰发展发挥作用；喷头保护范围和系统形式决定“哪里能出水”，不能只背设备名称。</li><li><strong>设备学习方法</strong>：先用“位置—作用—状态—证据—边界”五问识别设备，再进入检测或故障卡。看到“有水”“有压力”“泵在转”时，必须继续追问证据属于哪一层、是否覆盖任务目标。</li></ul><h2 id="_3-2-1-六类水系统设备零基础学习卡" tabindex="-1">3.2.1 六类水系统设备零基础学习卡 <a class="header-anchor" href="#_3-2-1-六类水系统设备零基础学习卡" aria-label="Permalink to &quot;3.2.1 六类水系统设备零基础学习卡&quot;">​</a></h2><p>下面每张卡都按同一顺序阅读：先知道它负责什么，再知道现场看什么，最后知道异常时不能做什么。</p><h3 id="a-消防水池与高位消防水箱" tabindex="-1">A. 消防水池与高位消防水箱 <a class="header-anchor" href="#a-消防水池与高位消防水箱" aria-label="Permalink to &quot;A. 消防水池与高位消防水箱&quot;">​</a></h3><ul><li><strong>是什么</strong>：储存并提供设计消防用水的设施；水池通常承担较大储水任务，高位水箱利用高度提供初期水源或压力条件。</li><li><strong>由什么组成</strong>：池体/箱体、进水、出水、补水、溢流、排水、液位显示或报警、防冻和检修相关部件，具体以工程配置为准。</li><li><strong>怎样工作</strong>：需要用水时，水从规定出水路径进入泵组或管网；液位变化、补水和溢流状态应与设计功能相符。</li><li><strong>正常证据</strong>：现场液位与控制室显示相互对应，进出水和补水路径明确，无异常渗漏、冻结或堵塞，标识和检修通道完整。</li><li><strong>异常处理</strong>：低水位、持续补水、渗漏、溢流或液位信号异常时，先记录位置、时间和影响范围，报告并评估保护能力；不得擅自放空、封堵或改变补水逻辑。</li></ul><h3 id="b-消防主泵、备用泵与稳压泵" tabindex="-1">B. 消防主泵、备用泵与稳压泵 <a class="header-anchor" href="#b-消防主泵、备用泵与稳压泵" aria-label="Permalink to &quot;B. 消防主泵、备用泵与稳压泵&quot;">​</a></h3><ul><li><strong>是什么</strong>：主泵和备用泵用于提供消防供水压力，稳压泵主要维持平时管网压力；三者职责和控制逻辑不能混为一谈。</li><li><strong>由什么组成</strong>：泵体、电动机、吸水/出水管路、阀门、止回部件、控制柜、压力采集和运行/故障反馈等。</li><li><strong>怎样工作</strong>：触发条件满足后，控制系统发出启动指令，泵组建立流量和压力，运行状态再通过触点或模块返回控制室。</li><li><strong>正常证据</strong>：控制方式和泵号正确，现场确有运行，压力/流量按方案变化，控制柜与控制室反馈一致，停止或切换后状态可恢复。</li><li><strong>异常处理</strong>：泵转但无压力、频繁启停或主备切换异常时，先区分供电、吸水、阀门、机械、水力、仪表和反馈问题；不得擅自关阀、改压力设定、拔反馈线或反复启停。</li></ul><h3 id="c-报警阀组与控制阀" tabindex="-1">C. 报警阀组与控制阀 <a class="header-anchor" href="#c-报警阀组与控制阀" aria-label="Permalink to &quot;C. 报警阀组与控制阀&quot;">​</a></h3><ul><li><strong>是什么</strong>：报警阀组负责分区供水控制并组织水流报警；控制阀/信号阀用于改变或监视管网通断状态。</li><li><strong>由什么组成</strong>：阀体、前后压力观察点、试水/排水路径、警铃或相关报警部件、信号机构、锁定/铅封和标识等，系统形式不同配置不同。</li><li><strong>怎样工作</strong>：分区出现规定水流或压力变化时，阀组及其附属部件产生水力、机械和电信号；控制阀处于规定位置才能保证保护范围成立。</li><li><strong>正常证据</strong>：阀门位置、锁定状态、标识与图纸一致，试水/排水路径可用，现场警铃、压力开关和控制室显示按方案对应。</li><li><strong>异常处理</strong>：阀门误关、试水有水但不报警或监管显示异常时，先评估受影响分区并报告；不得为消除显示而屏蔽、拆线、拆阀组或擅自改变阀位。</li></ul><h3 id="d-水流指示器与压力开关" tabindex="-1">D. 水流指示器与压力开关 <a class="header-anchor" href="#d-水流指示器与压力开关" aria-label="Permalink to &quot;D. 水流指示器与压力开关&quot;">​</a></h3><ul><li><strong>是什么</strong>：水流指示器主要报告某一分区出现水流；压力开关感知压力变化并输出电信号，可能参与报警或启泵，具体逻辑以设计为准。</li><li><strong>由什么组成</strong>：水流部件或压力采集部件、信号线、模块/端子和控制器输入，不能只看现场机械部件。</li><li><strong>怎样工作</strong>：水流或压力变化先作用于现场部件，再经线路和模块传到控制器；现场动作、模块输入和控制器显示是三个可分开的证据。</li><li><strong>正常证据</strong>：测试条件和分区明确，现场机构动作，控制器收到正确类别和区域的信号，测试后机构与显示均能复归。</li><li><strong>异常处理</strong>：有水无信号、现场机构不动作或显示分区错误时，分别核对方向/取压、接线、模块、映射和复位条件；不得短接输入伪造反馈。</li></ul><h3 id="e-末端试水装置与排水设施" tabindex="-1">E. 末端试水装置与排水设施 <a class="header-anchor" href="#e-末端试水装置与排水设施" aria-label="Permalink to &quot;E. 末端试水装置与排水设施&quot;">​</a></h3><ul><li><strong>是什么</strong>：末端试水装置在指定测试点制造可控水流，用于观察该点的水力现象及报警反馈；排水设施负责安全排走试验用水。</li><li><strong>由什么组成</strong>：试水阀、压力表或测量接口、试水接头、排水管路、标识和防滑/防淹条件。</li><li><strong>怎样工作</strong>：按方案缓慢开启后，水流经过测试路径，产生压力、出水、排水和信号变化；关闭后应确认无渗漏并恢复系统状态。</li><li><strong>正常证据</strong>：测试点、分区和方案明确，压力/流量记录有测点和单位，排水通畅，现场与控制室信号对应，阀门和自动状态恢复。</li><li><strong>异常处理</strong>：排水不畅、压力异常或有水无报警时，停止扩大影响，保留原始记录并报告；单点有水不能证明全系统合格。</li></ul><h3 id="f-水泵接合器、消火栓与喷头" tabindex="-1">F. 水泵接合器、消火栓与喷头 <a class="header-anchor" href="#f-水泵接合器、消火栓与喷头" aria-label="Permalink to &quot;F. 水泵接合器、消火栓与喷头&quot;">​</a></h3><ul><li><p><strong>是什么</strong>：水泵接合器为消防车向建筑消防管网补水或加压提供接口；消火栓提供人员取水组件；喷头按系统类型和动作条件出水。</p></li><li><p><strong>由什么组成</strong>：接合器接口、止回/放水部件和标识；消火栓箱、水带、水枪、栓阀和标识；喷头本体、温感元件和安装连接，具体按设备资料核对。</p></li><li><p><strong>怎样工作</strong>：接合器把外部供水接入规定管网，消火栓通过栓阀形成出水路径，喷头在满足动作条件后按方向和类型喷水。</p></li><li><p><strong>正常证据</strong>：位置和通道可达，接口/箱内组件/喷头外观完整，无遮挡、污染、碰撞和非授权改造，相关阀门及标识清楚。</p></li><li><p><strong>异常处理</strong>：接口损坏、箱内缺件、喷头遮挡或碰撞时，先保护现场、记录并报告；不得拆卸喷头、带压修理或用临时物件替代关键部件。</p></li><li><p><strong>建筑防火</strong>：防火分区、危险等级、冻结风险和使用场所影响系统选型、分区和管网布置。</p></li><li><p><strong>电气消防</strong>：泵组控制柜、主备电和反馈回路把水力动作转成可监视的电信号；“现场动作”和“控制室反馈”是两个证据。</p></li><li><p><strong>检测与维修</strong>：水系统检测遵循“前置—方法—显示—动作—反馈—恢复—记录”；异常时先区分水力问题、机械问题、信号问题和状态恢复问题。</p></li></ul><h2 id="_3-3-分设备检测方法" tabindex="-1">3.3 分设备检测方法 <a class="header-anchor" href="#_3-3-分设备检测方法" aria-label="Permalink to &quot;3.3 分设备检测方法&quot;">​</a></h2><p>分设备检测不是把所有对象都用同一个动作验证，而是为每个对象建立“对象—条件—方法—证据—恢复”链。具体阈值、动作时间、允许误差和抽检比例必须引用适用标准、设计文件、设备说明书或检测方案，不使用未经核验的统一数值。</p><table tabindex="0"><thead><tr><th>设备/部位</th><th>检测前确认</th><th>检测方法与观察证据</th><th>结果与边界</th></tr></thead><tbody><tr><td>水源、水池/水箱</td><td>水位、补水、进出水、溢流、环境和检修影响</td><td>查阅资料并现场核对状态；按方案观察补水、出水、液位显示和异常渗漏</td><td>有水不等于吸水条件、储水功能和信号均正常；容量结论须依设计/现行依据</td></tr><tr><td>主泵/备用泵</td><td>授权、供电、控制方式、吸水/出水阀、排水和监护</td><td>按方案启动或观察自动启动；记录运行、压力变化、异常声音/振动、运行/故障反馈</td><td>电机运行不等于供水合格；不得为测试擅自关闭阀门或制造故障</td></tr><tr><td>稳压泵及压力部件</td><td>自动状态、压力表/传感器标识、近期启停和渗漏记录</td><td>在规定条件下观察启停、压力变化和控制柜反馈；比对仪器记录与现场显示</td><td>频繁启停需结合渗漏、稳压部件和控制逻辑判断；不得擅自改设定</td></tr><tr><td>报警阀组/水力警铃</td><td>阀组状态、试水/排水路径、告知与防误启动措施</td><td>按方案进行试水或试警铃，观察水流、警铃、压力开关、控制器显示和排水</td><td>试水有水不代表报警链完整；警铃不响要区分水力通路与信号问题</td></tr><tr><td>信号阀/控制阀</td><td>标识、规定位置、锁定/铅封、监管反馈和保护影响</td><td>以现场位置与控制室状态交叉核对；状态变化检测须经批准并有监护</td><td>不得擅自改变消防给水状态；位置正确但无反馈仍需查信号链</td></tr><tr><td>水流指示器/压力开关</td><td>分区、方向、接线、取压条件、复位条件</td><td>通过方案指定水流或压力变化，分别观察现场机构、控制器输入和复位</td><td>现场机构动作与控制器收到信号是不同证据，不能相互替代</td></tr><tr><td>末端试水/排水设施</td><td>测试点、排水能力、防滑、电气防护和恢复条件</td><td>缓慢放水，记录压力、排水、水流指示、报警、泵反馈和控制室显示</td><td>单个测试点只能说明该点测试结果，不能外推全系统能力</td></tr><tr><td>喷头、消火栓、接合器</td><td>类型、方向、遮挡、污染、箱内组件、接口和通道</td><td>以外观、组件完整性、通道、阀门状态和方案允许的功能验证为证据</td><td>不得拆卸喷头或未经授权放水；静态有水不等于出水功能完成</td></tr></tbody></table><h2 id="_3-4-检测前—检测中—检测后" tabindex="-1">3.4 检测前—检测中—检测后 <a class="header-anchor" href="#_3-4-检测前—检测中—检测后" aria-label="Permalink to &quot;3.4 检测前—检测中—检测后&quot;">​</a></h2><p>先把水系统检测理解为“观察一条供水链是否在规定条件下成立”，而不是“打开一个阀门看看有没有水”。每一步都要说明观察对象和证据来源。</p><ol><li><strong>检测前</strong>：确认对象、区域、目的、授权、方案、图纸、设备资料、仪器状态与记录字段；通知控制室和受影响岗位，核对水源、阀门、供电、自动/联动、排水、防冻、人员和临时防护。特别要先区分本次是在看水力能力、机械动作、控制信号，还是做维修后的复测。</li><li><strong>检测中</strong>：按方案触发，不跨越授权边界；同时记录输入/触发、控制器显示、现场动作、压力/流量等实测及单位、仪器和时间；将现场动作、运行/故障反馈、分区信号和控制室显示分别取证。压力表读数属于一个测点的证据，必须连同测点、流量、阀门状态和测试条件理解。</li><li><strong>检测后</strong>：按方案停止放水或试验，确认无渗漏、排水完成、阀门和控制柜恢复规定状态；核对自动/联动/监视、控制室故障和报警信息，记录未解决异常、临时措施、判定依据、报告对象和复核人。设备停止只是动作结束，阀门、供电、控制方式、排水和监视状态都恢复，才算完成收口。</li></ol><h3 id="零基础记录示例-末端试水" tabindex="-1">零基础记录示例：末端试水 <a class="header-anchor" href="#零基础记录示例-末端试水" aria-label="Permalink to &quot;零基础记录示例：末端试水&quot;">​</a></h3><p>不要只写“末端试水有水，正常”。至少按下面顺序记录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>测试对象：哪一个分区、哪一个末端测试点</span></span>
<span class="line"><span>测试目的：验证末端水力现象，还是验证报警/反馈链</span></span>
<span class="line"><span>测试前：控制阀、信号阀、排水、供电、自动/联动和监护状态</span></span>
<span class="line"><span>触发过程：何时开启、由谁操作、采用什么方法</span></span>
<span class="line"><span>水力证据：压力、流量、出水和排水现象，注明单位和测点</span></span>
<span class="line"><span>机械证据：水流指示器、报警阀、水力警铃、泵组是否动作</span></span>
<span class="line"><span>控制证据：控制器显示的区域、类别、时间和反馈</span></span>
<span class="line"><span>恢复结果：试水阀、阀门、泵组、自动/联动、监视和排水是否恢复</span></span>
<span class="line"><span>异常处理：未恢复项目、临时措施、报告对象和复核人</span></span></code></pre></div><p>如果现场只有“有水”这一项证据，只能说明测试点出现了出水现象，不能直接判定报警链、泵组、反馈或全系统供水能力合格。</p><h2 id="_3-5-水系统故障诊断卡" tabindex="-1">3.5 水系统故障诊断卡 <a class="header-anchor" href="#_3-5-水系统故障诊断卡" aria-label="Permalink to &quot;3.5 水系统故障诊断卡&quot;">​</a></h2><p>以下诊断卡用于训练“现象—原因—判断—排查—边界”，不替代停用审批、设备说明书、检测方案或专业维修。</p><h3 id="卡-1-泵运行但压力不上升" tabindex="-1">卡 1：泵运行但压力不上升 <a class="header-anchor" href="#卡-1-泵运行但压力不上升" aria-label="Permalink to &quot;卡 1：泵运行但压力不上升&quot;">​</a></h3><ul><li><strong>现象</strong>：电机有运行迹象，压力显示未按预期变化。</li><li><strong>原因</strong>：水位或吸水条件不足、阀门状态异常、泵体/旋向/机械问题、仪表失真、管网泄漏或反馈误判。</li><li><strong>判断</strong>：先区分“泵未真正运行”“泵运行但水力异常”“压力显示异常”“运行反馈异常”。</li><li><strong>排查</strong>：记录时间和控制方式，核对水源、水位、吸水/出水条件、泵体异常、压力仪表与控制室反馈，按授权停机/隔离并报告。</li><li><strong>边界</strong>：不得为验证擅自关阀、拆泵、改设定或长时间盲目运行。</li></ul><h3 id="卡-2-备用泵未按逻辑投入" tabindex="-1">卡 2：备用泵未按逻辑投入 <a class="header-anchor" href="#卡-2-备用泵未按逻辑投入" aria-label="Permalink to &quot;卡 2：备用泵未按逻辑投入&quot;">​</a></h3><ul><li><strong>现象</strong>：主泵异常或测试条件满足时，备用泵没有预期动作。</li><li><strong>原因</strong>：控制方式不符、供电/控制回路异常、阀门或水源条件不满足、切换逻辑/反馈故障。</li><li><strong>判断</strong>：确认触发条件是否真实满足，再区分未发出启动、已发出未运行、运行无反馈。</li><li><strong>排查</strong>：核对主备泵编号、控制柜状态、供电、预期逻辑、泵组现场状态和反馈记录；仅按批准方案复测。</li><li><strong>边界</strong>：不得拔线、断电或人为制造主泵故障来验证切换。</li></ul><h3 id="卡-3-稳压泵频繁启停" tabindex="-1">卡 3：稳压泵频繁启停 <a class="header-anchor" href="#卡-3-稳压泵频繁启停" aria-label="Permalink to &quot;卡 3：稳压泵频繁启停&quot;">​</a></h3><ul><li><strong>现象</strong>：短时间内反复启动、停止或压力显示波动明显。</li><li><strong>原因</strong>：管网渗漏、用水/排水未恢复、稳压部件异常、压力采集波动或控制设定问题。</li><li><strong>判断</strong>：结合阀门状态、近期试水、渗漏迹象和压力记录，先排除人为放水和明显泄漏。</li><li><strong>排查</strong>：记录启停时间与压力变化，检查可见渗漏、试水阀复位、压力表/传感器和控制柜状态，升级授权人员处理设定或部件问题。</li><li><strong>边界</strong>：不得自行调整压力设定、封堵泄漏或以断电停止报警。</li></ul><h3 id="卡-4-末端试水有水但无控制室信号" tabindex="-1">卡 4：末端试水有水但无控制室信号 <a class="header-anchor" href="#卡-4-末端试水有水但无控制室信号" aria-label="Permalink to &quot;卡 4：末端试水有水但无控制室信号&quot;">​</a></h3><ul><li><strong>现象</strong>：测试点放水，现场可见水流，控制器无预期显示。</li><li><strong>原因</strong>：水流指示器/压力开关未动作、模块或线路异常、分区映射错误、控制器输入故障。</li><li><strong>判断</strong>：把水力现象、现场机构动作、输入信号和控制器显示分开记录。</li><li><strong>排查</strong>：核对测试点与分区、方向、取压/水流部件、接线、模块、控制器历史和复位状态，按方案复测并报告。</li><li><strong>边界</strong>：不得短接输入、反复放水或据此宣布全系统合格。</li></ul><h3 id="卡-5-报警阀试水不报警" tabindex="-1">卡 5：报警阀试水不报警 <a class="header-anchor" href="#卡-5-报警阀试水不报警" aria-label="Permalink to &quot;卡 5：报警阀试水不报警&quot;">​</a></h3><ul><li><strong>现象</strong>：试水时有排水或压力变化，警铃或控制室报警未出现。</li><li><strong>原因</strong>：阀组状态、试水通路、过滤/延迟部件、警铃水路、压力开关或信号回路异常。</li><li><strong>判断</strong>：确认是否形成方案要求的水力条件，再分别验证现场警铃与电信号链。</li><li><strong>排查</strong>：记录阀门和排水状态，检查试水路径、警铃通路、相关部件、压力开关、模块和控制器显示。</li><li><strong>边界</strong>：不得拆卸阀组内部、擅自改变设定或扩大放水范围。</li></ul><h3 id="卡-6-信号阀位置正常但显示监管异常" tabindex="-1">卡 6：信号阀位置正常但显示监管异常 <a class="header-anchor" href="#卡-6-信号阀位置正常但显示监管异常" aria-label="Permalink to &quot;卡 6：信号阀位置正常但显示监管异常&quot;">​</a></h3><ul><li><strong>现象</strong>：现场看似处于规定位置，控制室仍显示阀门监管异常。</li><li><strong>原因</strong>：监视机构未复位、接线/模块异常、位置与标识不一致或控制器输入故障。</li><li><strong>判断</strong>：现场位置、机构状态、线路输入和控制器显示必须分别核实。</li><li><strong>排查</strong>：保留异常时间，核对锁定/铅封、机构、接线、模块、端子和控制器事件记录，按授权进行复测。</li><li><strong>边界</strong>：不得为消除显示而屏蔽监管、拆线或直接删记录。</li></ul><h3 id="卡-7-管网或阀组持续渗漏" tabindex="-1">卡 7：管网或阀组持续渗漏 <a class="header-anchor" href="#卡-7-管网或阀组持续渗漏" aria-label="Permalink to &quot;卡 7：管网或阀组持续渗漏&quot;">​</a></h3><ul><li><strong>现象</strong>：法兰、螺纹、阀体或管道出现滴漏、积水或压力下降。</li><li><strong>原因</strong>：密封老化、连接松动、腐蚀、冻结损伤、异常压力或部件损坏。</li><li><strong>判断</strong>：先评估保护范围、泄漏位置、压力变化和放水风险，区分可观察渗漏与可能扩大故障。</li><li><strong>排查</strong>：设置警戒和防滑，记录位置、时间和状态，按停用流程报告、隔离和安排专业维修，维修后按方案复测。</li><li><strong>边界</strong>：不得带压拆卸、随意紧固关键部件、堵漏替代维修或无审批放空系统。</li></ul><h3 id="卡-8-动作后泵停、阀门或试水状态未恢复" tabindex="-1">卡 8：动作后泵停、阀门或试水状态未恢复 <a class="header-anchor" href="#卡-8-动作后泵停、阀门或试水状态未恢复" aria-label="Permalink to &quot;卡 8：动作后泵停、阀门或试水状态未恢复&quot;">​</a></h3><ul><li><strong>现象</strong>：试验已结束，但控制柜手动、阀门未复位、控制器仍有故障或排水未完成。</li><li><strong>原因</strong>：恢复步骤遗漏、联动/自动状态未切回、信号未复位、渗漏或原故障仍在。</li><li><strong>判断</strong>：以恢复清单和控制室/现场双重确认判断是否完成，不以“设备停止”代替恢复。</li><li><strong>排查</strong>：逐项核对试水阀、控制阀、供电、自动/联动、排水、监视和故障信息，记录无法恢复项并报告。</li><li><strong>边界</strong>：不得清除故障、屏蔽信号或关闭设备来伪造完成。</li></ul><h2 id="_3-6-检测、维修、保养的理论关联" tabindex="-1">3.6 检测、维修、保养的理论关联 <a class="header-anchor" href="#_3-6-检测、维修、保养的理论关联" aria-label="Permalink to &quot;3.6 检测、维修、保养的理论关联&quot;">​</a></h2><ul><li><strong>系统原理</strong>决定检测路径：水源、静压/动压、分区控制和末端出水解释“为什么要同时看水力、机械和信号证据”。</li><li><strong>建筑防火</strong>决定保护范围与系统边界：分区、冻结风险、危险等级和使用环境影响系统形式、阀组配置和测试影响，不能脱离设计文件泛化。</li><li><strong>电气消防</strong>解释泵控制柜、压力开关、水流指示器和反馈回路如何把水力变化转换为控制室信息；现场动作不等于反馈成立。</li><li><strong>检测理论</strong>要求可追溯：方法、条件、仪器、读数、显示、动作、反馈、判定依据和复测缺一项都可能造成结论失真。</li><li><strong>维修与保养理论</strong>要求先保护功能再处理缺陷：保养发现的是状态变化，维修解决的是故障原因，检测验证的是规定条件下的结果，三者不能用一张“外观正常”记录互相替代。</li></ul><h2 id="_4-四类自动喷水系统对比" tabindex="-1">4. 四类自动喷水系统对比 <a class="header-anchor" href="#_4-四类自动喷水系统对比" aria-label="Permalink to &quot;4. 四类自动喷水系统对比&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">2019版考试范围边界</p><p>在《消防设施操作员国家职业技能标准（2019年版）》检测维修保养方向的 5.2 分项中，正式明列的是<strong>湿式、干式自动喷水灭火系统</strong>。预作用、雨淋放在本节仅用于建立系统认知，不能当作该版本中级检测维修保养方向的独立技能考点；是否涉及，以当前适用的考核大纲和报考批次要求为准。</p></div><table tabindex="0"><thead><tr><th>类型</th><th>基本状态与动作逻辑</th><th>适用理解与边界</th></tr></thead><tbody><tr><td>湿式</td><td>管网通常充有有压水，闭式喷头动作后出水并触发水流报警</td><td>适用于设计允许的环境；低温、腐蚀、高温等限制须看设计，不能泛化</td></tr><tr><td>干式</td><td>管网通常充有有压气体，喷头动作后先排气，再由供水进入管网</td><td>适用于有冻结风险等设计场景；排气和充水会带来动作延迟</td></tr><tr><td>预作用</td><td>由预作用控制逻辑控制充水，喷头与控制条件按设计配合</td><td>用于降低误喷或特殊保护风险；不得把某一种预作用逻辑套用于所有工程</td></tr><tr><td>雨淋</td><td>采用开式喷头，满足启动条件后保护区集中喷水</td><td>用于特定危险场所或区域；启动可能造成较大范围放水，试验须严格审批</td></tr></tbody></table><blockquote><p>本节是理论扩展。系统分类、组件配置、启动条件、保护等级和性能判定属于设计及现行标准项目，考试或现场结论不得仅凭表格作出。</p></blockquote><h2 id="_5-水流与报警信号链" tabindex="-1">5. 水流与报警信号链 <a class="header-anchor" href="#_5-水流与报警信号链" aria-label="Permalink to &quot;5. 水流与报警信号链&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>末端试水/喷头放水</span></span>
<span class="line"><span>  → 管网水流变化</span></span>
<span class="line"><span>  → 水流指示器（分区信号）/报警阀组</span></span>
<span class="line"><span>  → 压力开关、水力警铃、延迟器（按系统配置）</span></span>
<span class="line"><span>  → 输入模块/消防控制器显示</span></span>
<span class="line"><span>  → 泵启动、运行/故障反馈（按设计逻辑）</span></span></code></pre></div><p>水流指示器主要帮助定位分区水流；压力开关可参与报警或启泵信号；报警阀组承担分区控制和水流报警功能；水力警铃是现场声响提示；延迟器用于特定系统中延缓短时水压波动造成的误报警。各信号的具体接线和联动关系应查图纸、说明书和方案。</p><h2 id="_6-现场状态与停用管理" tabindex="-1">6. 现场状态与停用管理 <a class="header-anchor" href="#_6-现场状态与停用管理" aria-label="Permalink to &quot;6. 现场状态与停用管理&quot;">​</a></h2><p>每次操作、保养或检测前后至少核对：阀门常开及锁定状态、水池/水箱水位、泵组和控制柜供电、泵房压力显示、自动/手动状态、排水路径、防冻措施、通道和环境。放水前确认排水能力、地面防滑和电气防护；低温区域关注管网、阀组和水源冻结风险。</p><div class="warning custom-block"><p class="custom-block-title">停用闭环</p><p>停用前确认影响区域和时限 → 审批并告知相关岗位 → 设置临时防护和巡查 → 记录停用阀门/设备 → 完成作业 → 恢复阀门、供电、自动/联动状态 → 现场与控制室双重确认并报告。</p></div><h2 id="_7-泵组启停与主备切换操作卡" tabindex="-1">7. 泵组启停与主备切换操作卡 <a class="header-anchor" href="#_7-泵组启停与主备切换操作卡" aria-label="Permalink to &quot;7. 泵组启停与主备切换操作卡&quot;">​</a></h2><ol><li>确认任务、区域、授权、供水条件、排水和人员安全；</li><li>核对主泵/备用泵/稳压泵、控制方式、供电、吸水和出水阀状态；</li><li>按设备说明书选择就地/远程、手动/自动方式并执行启动；</li><li>观察泵运行、压力变化、异常声音/振动、控制柜指示、运行/故障反馈和控制室显示；</li><li>按方案进行主备切换时，记录切换对象、触发条件和结果，不自行制造故障；</li><li>停泵仅在授权和任务允许时进行，随后恢复自动/联动并记录。</li></ol><blockquote><p>电机转动、控制柜亮灯或压力表有读数，都不能单独证明供水功能合格；判定还需按方案核对阀门、水源、压力/流量测量、反馈和恢复。</p></blockquote><h2 id="_8-末端试水与报警阀试验卡" tabindex="-1">8. 末端试水与报警阀试验卡 <a class="header-anchor" href="#_8-末端试水与报警阀试验卡" aria-label="Permalink to &quot;8. 末端试水与报警阀试验卡&quot;">​</a></h2><blockquote><p>末端试水主要用于检验测试点的启动、报警和联动过程，并记录该测试点的压力、流量等结果；不能用单个末端试水点的数据推算整个系统的供水能力、最不利点性能或全系统合格性。</p></blockquote><ul><li>查方案确定测试点、预期信号、允许放水方式和恢复要求；</li><li>通知控制室及受影响岗位，确认排水、防误启动和监护措施；</li><li>缓慢开启试水装置或按方案进行报警阀试验，观察水流、压力、警铃、控制器显示、压力开关、水流指示器和泵组反馈；</li><li>记录实际测量值及仪器信息，不能凭记忆填写统一压力、流量或持续时间；</li><li>按方案关闭试水/试验阀，确认无渗漏，恢复控制阀、控制柜自动/联动和控制室正常监视。</li></ul><h2 id="_9-保养卡" tabindex="-1">9. 保养卡 <a class="header-anchor" href="#_9-保养卡" aria-label="Permalink to &quot;9. 保养卡&quot;">​</a></h2><p>按“外观—连接—状态—功能—记录”执行：清洁并检查泵、阀组、管道、喷头、箱体和标识；查看渗漏、锈蚀、压力、水位、供电、阀门锁定和环境；按授权计划验证功能。不得以外观整洁替代功能检测，不得擅自调整设定、拆卸喷头、堵塞排水或改变阀门状态。</p><h2 id="_10-检测五项结果" tabindex="-1">10. 检测五项结果 <a class="header-anchor" href="#_10-检测五项结果" aria-label="Permalink to &quot;10. 检测五项结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结果</th><th>水系统记录示例</th></tr></thead><tbody><tr><td>输入/触发</td><td>末端试水、报警阀试水、模拟信号或方案指定触发</td></tr><tr><td>显示</td><td>控制器显示的区域、设备、类别和时间</td></tr><tr><td>动作</td><td>水流、警铃、泵组、阀门或喷头相关动作</td></tr><tr><td>反馈</td><td>水流指示器、压力开关、泵运行/故障和控制室信号</td></tr><tr><td>恢复</td><td>试水阀、控制阀、控制柜自动/联动、排水和监视状态</td></tr></tbody></table><p>判定依据必须写明标准/版本、设计文件、设备说明书或检测方案；量值、允许误差和动作时间不使用未经核对的统一阈值。施工验收或调试条款中的时间、压力、声级等数值，只能在对应条款适用场景下引用，不能直接改写成日常保养通用阈值。</p><h2 id="_11-故障树-先现象-后原因" tabindex="-1">11. 故障树：先现象，后原因 <a class="header-anchor" href="#_11-故障树-先现象-后原因" aria-label="Permalink to &quot;11. 故障树：先现象，后原因&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>优先排查方向（仅为授权排查框架）</th></tr></thead><tbody><tr><td>泵启动无压/压力异常</td><td>水位、吸水条件、阀门、旋向/机械、仪表、管网泄漏和反馈；禁止只看电机</td></tr><tr><td>稳压泵频繁启停</td><td>渗漏、压力波动、气压/稳压部件、设定和控制回路；设定调整交专业人员</td></tr><tr><td>末端无水</td><td>控制阀、分区、管网堵塞/冻结、水源和排水条件</td></tr><tr><td>水流指示器不动作</td><td>水流方向、浆片/机构、分区接线、模块和复位状态</td></tr><tr><td>压力开关不动作</td><td>压力变化、取压/接线、模块、设定和设备故障</td></tr><tr><td>报警阀不报警</td><td>阀组状态、试水/排水、警铃通路、延迟器、压力和信号回路</td></tr><tr><td>管道/阀组漏水</td><td>密封、连接、腐蚀、冻结损伤和异常压力；先隔离并报告</td></tr><tr><td>阀门误关</td><td>核对标识、锁定和监视，评估保护范围，启动停用与临时防护流程</td></tr><tr><td>冻结</td><td>环境、防冻措施、受冻部位和系统损伤；不得未经评估强行操作</td></tr><tr><td>动作但无反馈</td><td>现场动作、模块/线路、控制器输入和供电分别验证</td></tr></tbody></table><h2 id="_12-维修边界与停用恢复" tabindex="-1">12. 维修边界与停用恢复 <a class="header-anchor" href="#_12-维修边界与停用恢复" aria-label="Permalink to &quot;12. 维修边界与停用恢复&quot;">​</a></h2><p>维修遵循“现象记录—判断—安全隔离—授权处理—功能验证—恢复记录”。普通操作员可报告、观察和按方案复核；涉及电气拆装、报警阀内部、泵体、压力设定、管网改造、喷头更换或联动逻辑的工作，由具备相应授权的专业人员执行。维修后须验证原故障消失、无新增故障、输入/显示/动作/反馈完整，并恢复规定阀门、供电、自动/联动/监视状态。</p><h2 id="_13-记录模板" tabindex="-1">13. 记录模板 <a class="header-anchor" href="#_13-记录模板" aria-label="Permalink to &quot;13. 记录模板&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>日期/时间：        区域/设备编号：</span></span>
<span class="line"><span>任务与方案：        依据文件及版本：</span></span>
<span class="line"><span>操作前：水位____ 压力____ 阀门____ 供电____ 控制方式____</span></span>
<span class="line"><span>方法/仪器及校准信息：</span></span>
<span class="line"><span>输入/触发：         控制器显示：</span></span>
<span class="line"><span>现场动作：          反馈信号：</span></span>
<span class="line"><span>测量值及单位：      判定依据：</span></span>
<span class="line"><span>异常与临时措施：</span></span>
<span class="line"><span>恢复状态（阀门、自动/联动、排水、监视）：</span></span>
<span class="line"><span>报告对象：          操作/检测人：        复核人：</span></span></code></pre></div><h2 id="_14-原创训练场景题" tabindex="-1">14. 原创训练场景题 <a class="header-anchor" href="#_14-原创训练场景题" aria-label="Permalink to &quot;14. 原创训练场景题&quot;">​</a></h2><blockquote><p>以下均为原创训练题，不是官方评分表或历年真题。</p></blockquote><h3 id="s-w01-·-泵启动但无压力" tabindex="-1">S-W01 · 泵启动但无压力 <a class="header-anchor" href="#s-w01-·-泵启动但无压力" aria-label="Permalink to &quot;S-W01 · 泵启动但无压力&quot;">​</a></h3><p><strong>场景</strong>：泵电机运行，压力未按预期变化。<br><strong>标准判断</strong>：不得宣布合格或继续盲目运行；记录现象，核对水位、吸水/出水阀、管网、仪表和反馈，按授权隔离、报告并复核。</p><h3 id="s-w02-·-末端试水无报警" tabindex="-1">S-W02 · 末端试水无报警 <a class="header-anchor" href="#s-w02-·-末端试水无报警" aria-label="Permalink to &quot;S-W02 · 末端试水无报警&quot;">​</a></h3><p><strong>场景</strong>：末端有放水，但控制室未显示预期信号。<br><strong>标准判断</strong>：记录试水点和时间，核对水流指示器、压力开关、模块、线路、控制器显示及排水，不得直接填写“系统正常”。</p><h3 id="s-w03-·-报警阀组试验无警铃" tabindex="-1">S-W03 · 报警阀组试验无警铃 <a class="header-anchor" href="#s-w03-·-报警阀组试验无警铃" aria-label="Permalink to &quot;S-W03 · 报警阀组试验无警铃&quot;">​</a></h3><p><strong>场景</strong>：试验有水流，现场水力警铃不响。<br><strong>标准判断</strong>：停止扩大试验，按方案核对警铃通路、试警铃阀、延迟器/过滤部件和渗漏，报告维修人员；测试后恢复并记录。</p><h3 id="s-w04-·-主备泵切换" tabindex="-1">S-W04 · 主备泵切换 <a class="header-anchor" href="#s-w04-·-主备泵切换" aria-label="Permalink to &quot;S-W04 · 主备泵切换&quot;">​</a></h3><p><strong>场景</strong>：按计划验证主泵与备用泵切换。<br><strong>标准判断</strong>：先核对授权、供电、阀门和预期触发条件；分别记录运行、压力、控制柜和控制室反馈，禁止拔线或人为制造故障，完成自动状态复归。</p><h3 id="s-w05-·-发现分区控制阀误关" tabindex="-1">S-W05 · 发现分区控制阀误关 <a class="header-anchor" href="#s-w05-·-发现分区控制阀误关" aria-label="Permalink to &quot;S-W05 · 发现分区控制阀误关&quot;">​</a></h3><p><strong>场景</strong>：巡检发现信号阀未处于规定常开状态。<br><strong>标准判断</strong>：评估影响区域，立即报告并按单位流程设置临时防护；不得无授权强行开启或仅在记录上写“已恢复”，须由责任人员确认。</p><h3 id="s-w06-·-测试后遗留手动状态" tabindex="-1">S-W06 · 测试后遗留手动状态 <a class="header-anchor" href="#s-w06-·-测试后遗留手动状态" aria-label="Permalink to &quot;S-W06 · 测试后遗留手动状态&quot;">​</a></h3><p><strong>场景</strong>：试水结束，设备停止，但控制柜仍手动且控制器有故障。<br><strong>标准判断</strong>：不能宣布完成；核实故障和保护影响，按权限恢复自动/联动，报告并记录复核结果。</p><h2 id="_15-依据与版本边界" tabindex="-1">15. 依据与版本边界 <a class="header-anchor" href="#_15-依据与版本边界" aria-label="Permalink to &quot;15. 依据与版本边界&quot;">​</a></h2><p>学习依据包括《消防设施操作员国家职业技能标准（2019年版）》、现行建筑消防给水及自动喷水灭火系统相关国家标准、地方鉴定站实施要求、项目设计文件、竣工资料和设备说明书。</p><ul><li><a href="https://ndls.org.cn/standard/detail/af2c361d544ecd02da7be14d268c1946" target="_blank" rel="noreferrer">GB 50261-2017《自动喷水灭火系统施工及验收规范》公开目录</a>：用于核对自动喷水灭火系统施工、验收及维护管理的标准范围；公开目录元数据为 2017-05-27 发布、2018-01-01 实施，具体条文和与通用规范的适用关系仍需复核。</li><li><a href="https://ndls.cnis.ac.cn/standard/detail/f206a7a67c68102d90a31f9515f75af3" target="_blank" rel="noreferrer">GB 50974-2014《消防给水及消火栓系统技术规范》公开目录</a>：用于核对消防给水、消火栓系统设计、施工和维护管理的标准范围；公开目录元数据为 2014-01-29 发布、2014-10-01 实施，具体条文和与通用规范的适用关系仍需复核。</li><li><a href="https://openstd.samr.gov.cn/" target="_blank" rel="noreferrer">国家标准全文公开系统</a>：用于核验现行标准文本、版本和适用范围。</li></ul><p>标准可能修订，页面不固化水箱容积、压力、流量、持续时间或动作时间等统一数值；使用时必须核对现行版本和现场方案。理论扩展用于理解系统，不得替代设计审查、检测报告或有资质人员的工程判断。</p>`,125)])])}const u=a(r,[["render",i]]);export{c as __pageData,u as default};
